// ─── File: ProxyComparisonDemo.java ───
// Forward proxy fronts CLIENTS (hides them from servers); reverse proxy fronts
// SERVERS (hides them from clients). Nginx / API gateway in front of services = reverse.
import java.util.*;
import java.util.logging.*;

public class ProxyComparisonDemo {
    private static final Logger log = Logger.getLogger("Proxy");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // FORWARD PROXY: employees reaching external sites.
        log.info("=== FORWARD PROXY (fronts clients, hides them from servers) ===");
        ForwardProxy forward = new ForwardProxy(Set.of("rbi.org.in", "npci.org.in"));
        forward.handleOutbound(new OutboundRequest("EMP-Rajesh", "npci.org.in"));   // allowed
        forward.handleOutbound(new OutboundRequest("EMP-Rajesh", "npci.org.in"));   // cached
        forward.handleOutbound(new OutboundRequest("EMP-Priya", "facebook.com"));   // blocked

        // REVERSE PROXY: customers reaching internal services.
        log.info("=== REVERSE PROXY (fronts servers, hides them from clients) ===");
        InternalService loan = new InternalService("loan-service:8080");
        InternalService pay = new InternalService("payment-service:8080");
        Map<String, InternalService> routes = new LinkedHashMap<>();
        routes.put("/api/loans", loan);
        routes.put("/api/payments", pay);
        ReverseProxy reverse = new ReverseProxy(routes);
        reverse.handleInbound(new InboundRequest("customer-SAV2001", "/api/loans"));
        reverse.handleInbound(new InboundRequest("customer-CUR3001", "/api/payments"));
    }
}

// ─── model/OutboundRequest.java ───
class OutboundRequest {
    final String employeeId, destination;
    OutboundRequest(String employeeId, String destination) {
        this.employeeId = employeeId; this.destination = destination;
    }
}

// ─── model/InboundRequest.java ───
class InboundRequest {
    final String clientId, path;
    InboundRequest(String clientId, String path) { this.clientId = clientId; this.path = path; }
}

// ─── forward/ForwardProxy.java (on the CLIENT side) ───
class ForwardProxy {
    private static final Logger log = Logger.getLogger("Proxy");
    private final Set<String> allowlist;             // egress filtering
    private final Set<String> outboundCache = new HashSet<>(); // caching outbound fetches
    ForwardProxy(Set<String> allowlist) { this.allowlist = allowlist; }

    void handleOutbound(OutboundRequest req) {
        if (!allowlist.contains(req.destination)) {
            log.warning(() -> "FORWARD blocked " + req.employeeId + " → " + req.destination
                    + " (not on allowlist)");
            return;
        }
        if (outboundCache.contains(req.destination)) {
            log.info(() -> "FORWARD served CACHED copy of " + req.destination
                    + " to " + req.employeeId);
            return;
        }
        // Destination sees the PROXY's IP, not the employee's — client is hidden.
        outboundCache.add(req.destination);
        log.info(() -> "FORWARD relayed " + req.employeeId + " → " + req.destination
                + " (dest sees proxy IP, employee hidden)");
    }
}

// ─── reverse/ReverseProxy.java (on the SERVER side) — what Nginx/API gateway is ───
class ReverseProxy {
    private static final Logger log = Logger.getLogger("Proxy");
    private final Map<String, InternalService> routes;
    ReverseProxy(Map<String, InternalService> routes) { this.routes = routes; }

    void handleInbound(InboundRequest req) {
        log.info(() -> "REVERSE terminated TLS for " + req.clientId);   // holds the cert
        InternalService backend = routes.get(req.path);                 // route by path
        if (backend == null) {
            log.warning(() -> "REVERSE 404 no route for " + req.path);
            return;
        }
        // Client never learns the backend host — servers are hidden.
        log.info(() -> "REVERSE routed " + req.path + " → " + backend.host()
                + " (client never sees backend host)");
        backend.serve(req);
    }
}

// ─── backend/InternalService.java (hidden behind the reverse proxy) ───
class InternalService {
    private static final Logger log = Logger.getLogger("Proxy");
    private final String host;
    InternalService(String host) { this.host = host; }
    String host() { return host; }
    void serve(InboundRequest req) {
        log.info(() -> "BACKEND " + host + " served " + req.path);
    }
}

// ─── config/BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
